/**
 * t233 — THE Kotlin page registry: EVERY pageId the web SPA serves
 * (src/lib/page-loader.ts + src/lib/page-chunks/) maps to a NATIVE Compose
 * screen here. RouteOwnership resolves registered ids to
 * [Destination.NativePage] FIRST — the `web/{pageId}` route is a LAST-RESORT
 * fallback for ids the SPA contract does not know (matching the SPA's own
 * isKnownPage(), which never rejects).
 *
 * One dynamic destination (`native/{pageId}`) hosts every entry: a per-pageId
 * route explosion would buy nothing — each entry's screen owns its own
 * Scaffold, metadata object and ViewModel key, and the registry entry is the
 * single binding point (map value → composable), checked into Kotlin.
 *
 * `tabLike` marks tab-root pages (bottom bar visible, no back arrow, pushed
 * with tab state semantics). `meta.tabHint` drives the bottom-bar highlight
 * (RouteOwnership.activeTabFor consults it before the alias map).
 */
object NativePageRegistry {

    /** One registry row: metadata + whether the page is a tab root + renderer. */
    class NativePageEntry(
        val meta: NativePageMeta,
        val tabLike: Boolean,
        val content: @Composable (
            onBack: (() -> Unit)?,
            openPage: (pageId: String, query: String) -> Unit,
            query: String,
        ) -> Unit,
    )

    fun knows(pageId: String): Boolean = all.containsKey(pageId)

    fun entryFor(pageId: String): NativePageEntry? = all[pageId]

    fun metaFor(pageId: String): NativePageMeta? = all[pageId]?.meta

    /** Bottom-bar highlight hint; null when the page has no tab preference. */
    fun tabHintFor(pageId: String): String? =
        all[pageId]?.meta?.tabHint?.takeIf { it.isNotBlank() }

    fun tabLike(pageId: String): Boolean = all[pageId]?.tabLike ?: false

    private fun entry(
        meta: NativePageMeta,
        tabLike: Boolean = false,
        content: @Composable (
            onBack: (() -> Unit)?,
            openPage: (pageId: String, query: String) -> Unit,
            query: String,
        ) -> Unit,
    ): NativePageEntry = NativePageEntry(meta, tabLike, content)

    /**
     * The registry itself. Hand-written cores (home/cart/orders/deals/search/
     * categories/profile/notifications/wishlist) + one generated screen per
     * remaining pageId. Auth suite pageIds (welcome/login/register-/otp/…)
     * and product-detail resolve through RouteOwnership's dedicated rows
     * BEFORE this table — they are parameterized native routes, not entries.
     */
